//! `confd` client and wire shapes (issue #260).
//!
//! The `os.lazy.confd.v1` stubs and the blocking [`Client`] are generated by
//! `midlc` into `messenger-generated`; this module adds the typed
//! [`confd::Value`] conversion ([`ValueClient`]) and the reply framing the
//! daemon still writes by hand.


use libmessenger::client::{CallError, Deadline, Errno, Transport};

use super::client::Native;
use super::{errno, Error, Result};

/// The generated `os.lazy.confd.v1` stubs.
pub use messenger_generated::os_lazy_confd_v1 as wire;
/// The generated helpers for the declared `system/confd/changed/#` topic, so
/// callers do not have to reach through [`wire`].
pub use messenger_generated::os_lazy_confd_v1::{
    decode_system_confd_changed, encode_system_confd_changed, name_system_confd_changed,
    publish_system_confd_changed,
};

/// Registered service name (the root object clients resolve).
pub const NAME: &str = wire::SERVICE_NAME;

/// The interface id every `confd` parcel carries.
pub const INTERFACE: u64 = wire::INTERFACE_ID;

/// The store's own failures (`errors` in `idl/confd.midl`), carried in the
/// reply's structured `ERROR` field outside the errno range so a client can
/// tell a store rejection from a transport failure.
pub use wire::ServiceError as StoreError;

/// A blocking client of the `confd` service: [`connect_waiting`] for a
/// program that may start before `confd`, [`connect`] for one attempt.
pub type Client = wire::Client<Native>;

/// Why a [`Client`] call failed: the store's own [`StoreError`] or a
/// transport failure.
pub type ClientError = wire::ClientError;

/// One attempt to reach `confd`: for a caller with a cheap fallback.
pub fn connect() -> core::result::Result<Client, ClientError> {
    Client::try_connect(Native)
}

/// A [`Client`] that waits for `confd` to register (a boot-time caller).
pub fn connect_waiting() -> core::result::Result<Client, ClientError> {
    Client::connect(Native)
}

/// The typed [`confd::Value`] over the generated client, which speaks the
/// wire [`wire::Value`].
pub trait ValueClient {
    /// `Get(path)`: `None` when the path is absent.
    fn get_value(&self, path: &str) -> core::result::Result<Option<confd::Value>, ClientError>;
    /// [`ValueClient::get_value`] with the caller's bound.
    fn get_value_within(
        &self,
        path: &str,
        within: Deadline,
    ) -> core::result::Result<Option<confd::Value>, ClientError>;
    /// `Set(path, value)`.
    fn set_value(&self, path: &str, value: &confd::Value) -> core::result::Result<(), ClientError>;
    /// [`ValueClient::set_value`] with the caller's bound.
    fn set_value_within(
        &self,
        path: &str,
        value: &confd::Value,
        within: Deadline,
    ) -> core::result::Result<(), ClientError>;
}

/// A reply value that does not decode is a malformed reply.
fn typed(value: wire::Value) -> core::result::Result<confd::Value, ClientError> {
    value_from_wire(&value).map_err(|_| CallError::Transport(Errno::BADMSG))
}

impl<T: Transport> ValueClient for wire::Client<T> {
    fn get_value(&self, path: &str) -> core::result::Result<Option<confd::Value>, ClientError> {
        self.get(path)?.map(typed).transpose()
    }

    fn get_value_within(
        &self,
        path: &str,
        within: Deadline,
    ) -> core::result::Result<Option<confd::Value>, ClientError> {
        self.get_within(path, within)?.map(typed).transpose()
    }

    fn set_value(&self, path: &str, value: &confd::Value) -> core::result::Result<(), ClientError> {
        self.set(path, &value_to_wire(value))
    }

    fn set_value_within(
        &self,
        path: &str,
        value: &confd::Value,
        within: Deadline,
    ) -> core::result::Result<(), ClientError> {
        self.set_within(path, &value_to_wire(value), within)
    }
}

/// Subscribe to change topics; the filter is a topic filter such as
/// `system/confd/changed/sys/#`. Nothing is replayed (changes are not
/// retained), so callers should `List`/`Get` once before watching.
pub fn watch(filter: &str) -> Result<crate::central::Subscription> {
    let mut bus = crate::central::Bus::connect()?;
    bus.subscribe(filter)
}

/// A store refusal as the fault the generated server answers with: the
/// declared code and its friendly text ([`store_message`]).
pub fn store_fault(error: confd::ServiceError) -> libmessenger::server::Fault {
    let declared = match error {
        confd::ServiceError::NotFound => StoreError::NotFound,
        confd::ServiceError::BadPath => StoreError::BadPath,
        confd::ServiceError::TooLarge => StoreError::TooLarge,
        confd::ServiceError::Denied => StoreError::Denied,
        confd::ServiceError::Io => StoreError::Io,
    };
    libmessenger::server::Fault::new(declared.code(), store_message(declared))
}

/// `confd::Value` -> the generated wire value.
pub fn value_to_wire(value: &confd::Value) -> wire::Value {
    let mut out = wire::Value::default();
    match value {
        confd::Value::Bool(flag) => {
            out.kind = wire::KIND_BOOL;
            out.bool_value = Some(*flag);
        }
        confd::Value::I64(number) => {
            out.kind = wire::KIND_I64;
            out.i64_value = Some(*number);
        }
        confd::Value::U64(number) => {
            out.kind = wire::KIND_U64;
            out.u64_value = Some(*number);
        }
        confd::Value::Str(text) => {
            out.kind = wire::KIND_STR;
            out.str_value = Some(text.clone());
        }
        confd::Value::Bytes(bytes) => {
            out.kind = wire::KIND_BYTES;
            out.bytes_value = Some(bytes.clone());
        }
    }
    out
}

/// The generated wire value -> `confd::Value`; a `kind` whose payload is
/// missing is rejected so a malformed request cannot become an empty value.
pub fn value_from_wire(value: &wire::Value) -> Result<confd::Value> {
    let invalid = || Error::Errno(-errno::EINVAL);
    match value.kind {
        wire::KIND_BOOL => value.bool_value.map(confd::Value::Bool).ok_or_else(invalid),
        wire::KIND_I64 => value.i64_value.map(confd::Value::I64).ok_or_else(invalid),
        wire::KIND_U64 => value.u64_value.map(confd::Value::U64).ok_or_else(invalid),
        wire::KIND_STR => value
            .str_value
            .clone()
            .map(confd::Value::Str)
            .ok_or_else(invalid),
        wire::KIND_BYTES => value
            .bytes_value
            .clone()
            .map(confd::Value::Bytes)
            .ok_or_else(invalid),
        _ => Err(invalid()),
    }
}

/// Friendly text for a store failure (the `errors` block of `idl/confd.midl`).
pub fn store_message(error: StoreError) -> &'static str {
    match error {
        StoreError::NotFound => "no value is stored at that path",
        StoreError::BadPath => "that is not a valid confd path",
        StoreError::TooLarge => "the value or store exceeds a confd size limit",
        StoreError::Denied => "the caller may not access that path",
        StoreError::BadValue => "the request carried a malformed confd value",
        StoreError::Io => "the confd store could not be read or written",
    }
}

/// The failure as an untyped [`CallError`], for a caller that shows its
/// text or forwards its code (`Display`, `message`, `code`).
pub fn flatten(error: ClientError) -> CallError {
    error.flatten(|store| {
        (
            store.code(),
            alloc::string::String::from(store_message(store)),
        )
    })
}

/// The failure as this crate's [`Error`], for a daemon whose own API
/// reports `Result<_, Error>`: a store refusal is [`Error::Confd`], a
/// transport failure its errno.
pub fn lower(error: ClientError) -> Error {
    match error {
        CallError::Transport(errno) => Error::Errno(errno.to_syscall()),
        CallError::Service(store) => Error::Confd(i64::from(store.code())),
        CallError::Remote { code, .. } => Error::Confd(i64::from(code)),
    }
}
